//! A concurrent process spawn can inherit a writer fd between fork and exec.
#[test]fn dropping_writer_releases_flock_even_while_fork_child_has_inherited_fd(){let d=tempfile::tempdir().unwrap();let id=uuid::Uuid::new_v4();let w=hs_log::StreamWriter::create(d.path(),id).unwrap();let mut pipe=[0;2];unsafe{assert_eq!(libc::pipe(pipe.as_mut_ptr()),0);let pid=libc::fork();assert!(pid>=0);if pid==0{libc::close(pipe[1]);let mut b=0u8;libc::read(pipe[0],(&mut b as *mut u8).cast(),1);libc::_exit(0);}libc::close(pipe[0]);drop(w);let resumed=hs_log::StreamWriter::resume(d.path(),id);libc::write(pipe[1],b"x".as_ptr().cast(),1);libc::close(pipe[1]);let mut status=0;libc::waitpid(pid,&mut status,0);assert!(resumed.is_ok(),"writer drop must release ownership, not wait for unrelated child exec: {:?}",resumed.err());}}
#[test]fn fork_child_drop_cannot_unlock_live_parent(){let d=tempfile::tempdir().unwrap();let id=uuid::Uuid::new_v4();let w=hs_log::StreamWriter::create(d.path(),id).unwrap();unsafe{let pid=libc::fork();assert!(pid>=0);if pid==0{drop(w);libc::_exit(0);}let mut status=0;libc::waitpid(pid,&mut status,0);assert!(matches!(hs_log::StreamWriter::resume(d.path(),id),Err(hs_log::LogError::StreamHeld(_))));drop(w);assert!(hs_log::StreamWriter::resume(d.path(),id).is_ok());}}
